<template><view class="row mb16"><picker mode="date" :value="date" @change="$emit('update:date',$event.detail.value)"><view class="filter-pill">{{date||'全部日期'}}⌄</view></picker><button v-if="date" class="text-button small" @tap="$emit('update:date','')">清除</button><FSelect :model-value="store" :options="options" @update:model-value="$emit('update:store',$event)"/></view></template>
<script setup>import {computed} from 'vue';import FSelect from './FSelect.vue';import {responsibleStores} from '../lib/food';defineProps({date:{default:''},store:{default:0}});defineEmits(['update:date','update:store']);const options=computed(()=>[{value:0,label:'全部负责门店'},...responsibleStores().map(s=>({value:s.id,label:s.name}))])</script>
